    const chips91 = () => canvasFrame().evaluate(() => [...document.querySelectorAll('[data-inflozo-chrome]')].reduce((n, h) => n + (h.shadowRoot?.querySelectorAll('[data-chrome="paused"]').length ?? 0), 0))
