    const whenOf104 = () => ts.locator('#promote-when').evaluate((g) => ({ disabled: g.getAttribute('aria-disabled'), reason: document.getElementById('promote-when-reason')?.textContent ?? null }))
    const whenNone104 = await whenOf104()
